// Guard Rail #2: Validate tenant_id and detect format (TEXT or UUID)
// Reference: docs/core/verified-research-findings.md PART 1 Pattern #3
// Production hardening: Accept both TEXT (phone/name) and UUID for flexibility

const input = $input.item.json;
const tenantId = input.tenant_id;

if (!tenantId) {
  return {
    valid: false,
    error: 'tenant_id is required',
    statusCode: 400
  };
}

if (typeof tenantId !== 'string' || tenantId.trim().length === 0) {
  return {
    valid: false,
    error: 'tenant_id must be a non-empty string',
    statusCode: 400
  };
}

// UUID regex pattern
const uuidRegex = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const trimmedId = tenantId.trim();
const isUUID = uuidRegex.test(trimmedId);

return {
  valid: true,
  tenant_id: trimmedId,
  tenant_id_input: trimmedId,
  is_uuid: isUUID,
  lookup_type: isUUID ? 'uuid' : 'text',
  phone: input.phone
};

// Resolve tenant UUID: Handle both TEXT (phone/name) and UUID inputs
// Production hardening: Always output UUID for downstream workflows

const validated = $input.item.json;
const tenantId = validated.tenant_id_input;
const isUUID = validated.is_uuid;

// Build query based on input type
let queryUrl;
if (isUUID) {
  // Direct UUID lookup
  queryUrl = `${process.env.SUPABASE_URL}/rest/v1/tenants?id=eq.${tenantId}&is_active=eq.true&limit=1`;
} else {
  // TEXT lookup: Try phone first, then name
  queryUrl = `${process.env.SUPABASE_URL}/rest/v1/tenants?or=(phone.eq.${tenantId},name.eq.${tenantId})&is_active=eq.true&limit=1`;
}

return {
  query_url: queryUrl,
  tenant_id_input: tenantId,
  is_uuid: isUUID,
  lookup_type: validated.lookup_type,
  phone: validated.phone
};

// Guard Rail #3: Check if tenant exists and extract UUID
// Production hardening: Always output UUID tenant_id for downstream workflows
// Reference: docs/core/verified-research-findings.md PART 1 Pattern #3

const tenantResult = $('Guard Rail #3: Verify tenant exists').first()?.json || [];
const validated = $('Guard Rail #2: Validate tenant_id').first().json;
const lookupInfo = $('Resolve Tenant Lookup').first().json;

if (!tenantResult || tenantResult.length === 0) {
  return {
    valid: false,
    error: 'Tenant not found or inactive',
    statusCode: 404,
    tenant_id_input: validated.tenant_id_input
  };
}

const tenant = tenantResult[0];
if (!tenant.is_active) {
  return {
    valid: false,
    error: 'Tenant is inactive',
    statusCode: 403,
    tenant_id_input: validated.tenant_id_input
  };
}

// Always return UUID tenant_id (for downstream workflows)
return {
  valid: true,
  tenant_id: tenant.id,  // UUID from tenants table
  tenant_id_input: validated.tenant_id_input,  // Original input (for logging)
  tenant: tenant,
  phone: validated.phone,
  lookup_type: lookupInfo.lookup_type
};

// Finalize tenant config with guard rail validation
// Reference: docs/core/verified-research-findings.md PART 1 Pattern #3

const tenantCheck = $('Check Tenant Exists').first().json;
const tenantConfig = $('Guard Rail #4: Load tenant config').first()?.json || [];

if (!tenantConfig || tenantConfig.length === 0) {
  return {
    error: 'Tenant config not found',
    statusCode: 500,
    tenant_id: tenantCheck.tenant_id
  };
}

return {
  tenant_config: tenantConfig[0],
  tenant_id: tenantCheck.tenant_id,
  tenant: tenantCheck.tenant,
  phone: tenantCheck.phone,
  found_by: 'guard_rails'
};
